create or replace procedure usrdrc.pendium_reportes_poderes_pkg_query_apoderados_pg (porcrsresultado inout refcursor ,pstdes_empresas varchar ,pstdes_tipopoder varchar ,pstdes_apoderados varchar ,pstdes_poder varchar ,pstdes_escritura varchar) as $body$
declare
