-- pgv moved types end
dinamicquery text;
begin
-- package does not have global variables
--dmap conversion comment: gtt declaration added
--[fec_otorgamiento_instr, nom_empresa, des_podertipo, ind_tipo_escritura, desc_actosdominio, desc_pleitoscobranza, fec_vigenciafin]
dinamicquery := 'SELECT (CASE WHEN PENDIUM_ESCRITURA_PODER_TAB.IND_REQUIERE_PROTO=1 AND NULLIF(PENDIUM_ESCRITURA_PODER_TAB.DES_ESCRITURA::text, '') IS NOT NULL THEN PENDIUM_ESCRITURA_PODER_TAB.DES_ESCRITURA ELSE ''N/A'' END) DES_ESCRITURA, (CASE WHEN PENDIUM_ESCRITURA_PODER_TAB.IND_REQUIERE_PROTO=1 AND NULLIF(PENDIUM_ESCRITURA_PODER_TAB.FEC_OTORGAMIENTO_INSTR::text, '') IS NOT NULL THEN PENDIUM_ESCRITURA_PODER_TAB.FEC_OTORGAMIENTO_INSTR ELSE PENDIUM_ESCRITURA_PODER_TAB.FEC_FECHA END) as FEC_OTORGAMIENTO_INSTR, coalesce(PENDIUM_ESCRITURA_PODER_TAB.FEC_FECHA, '''') as fec_fecha, (select val_cat_val from usrdrc.dercorp_add_campo_cat_val_tab where id_catalogo = 1 and id_catalogo_valor = (select val_valor from usrdrc.dercorp_add_campo_valor_tab where id_empresa = dercorp_empresa_tab.id_empresa and id_add_campo = 500)) as nom_empresa, pendium_otorgapoder_ep_tab.des_podertipo, pendium_escritura_poder_tab.ind_tipo_escritura, coalesce(pendium_otorgapoder_ep_tab.des_poder, '''') as des_poder, coalesce(pendium_otorgapoder_ep_tab.desc_actosdominio, '''') as desc_actosdominio, coalesce(pendium_otorgapoder_ep_tab.desc_actosadmon, '''') as desc_actosadmon, coalesce(pendium_otorgapoder_ep_tab.desc_pleitoscobranza, '''') as desc_pleitoscobranza, coalesce(pendium_otorgapoder_ep_tab.desc_tituloscredito, '''') as desc_tituloscredito, coalesce(pe.des_poder, '''') as desc_poder_especial, pendium_apoderado_ep_tab.desc_nom_empl, pendium_apoderado_ep_tab.ind_aprevoca, pendium_apoderado_ep_tab.desc_revoca, pendium_escritura_poder_tab.ind_status, dercorp_empresa_tab.id_empresa as id_empresa1, pendium_apoderado_ep_tab.id_empl_fk, coalesce(pendium_otorgapoder_ep_tab.fec_vigenciafin, '''') as fec_vigenciafin from pendium_apoderado_ep_tab inner join pendium_otorgapoder_ep_tab on pendium_otorgapoder_ep_tab.id_opoder_ep_pk = pendium_apoderado_ep_tab.id_opoder_ep_fk inner join pendium_escritura_poder_tab on pendium_escritura_poder_tab.id_ep_pk = pendium_otorgapoder_ep_tab.id_ep_fk inner join dercorp_empresa_tab on dercorp_empresa_tab.id_empresa = pendium_escritura_poder_tab.id_empresa left join pendium_otorgapoder_ep_tab pe join pendium_escritura_poder_tab esc_b on (esc_b.id_ep_pk = pe.id_ep_fk and esc_b.ind_tipo_escritura = ''pe'' and esc_b.ind_status = 1 and pe.ind_status = 1) on trim(both to_char(pendium_otorgapoder_ep_tab.des_poder)) = pe.des_podertipo and esc_b.id_empresa = pendium_escritura_poder_tab.id_empresa and pendium_escritura_poder_tab.des_escritura = esc_b.des_escritura and pendium_escritura_poder_tab.ind_delegado_por = esc_b.ind_delegado_por and coalesce(pendium_escritura_poder_tab.fec_fecha, '' '') = coalesce(esc_b.fec_fecha, '' '') and coalesce(pendium_escritura_poder_tab.num_documentum_instr, '' '') = coalesce(esc_b.num_documentum_instr, '' '') and coalesce(pendium_escritura_poder_tab.fec_otorgamiento_instr, '' '') = coalesce(esc_b.fec_otorgamiento_instr, '' '') and pendium_escritura_poder_tab.num_licenciado = esc_b.num_licenciado and coalesce(pendium_escritura_poder_tab.num_insc_regpub, '' '') = coalesce(esc_b.num_insc_regpub, '' '') and coalesce(pendium_escritura_poder_tab.fec_registro, '' '') = coalesce(esc_b.fec_registro, '' '') where pendium_otorgapoder_ep_tab.id_opoder_ep_pk not in (select pendium_otorgapoder_ep_tab.id_opoder_ep_pk from pendium_otorgapoder_ep_tab inner join pendium_otorgapoder_ep_tab pendium_otorgapoder_ep_tab1 on pendium_otorgapoder_ep_tab.des_podertipo = trim(both to_char(pendium_otorgapoder_ep_tab1.des_poder)) inner join pendium_escritura_poder_tab on pendium_escritura_poder_tab.id_ep_pk = pendium_otorgapoder_ep_tab.id_ep_fk inner join pendium_escritura_poder_tab pendium_escritura_poder_tab1 on pendium_escritura_poder_tab1.id_ep_pk = pendium_otorgapoder_ep_tab1.id_ep_fk and pendium_escritura_poder_tab1.id_empresa = pendium_escritura_poder_tab.id_empresa where pendium_escritura_poder_tab1.des_escritura = pendium_escritura_poder_tab.des_escritura and pendium_escritura_poder_tab.ind_delegado_por = pendium_escritura_poder_tab1.ind_delegado_por and coalesce(pendium_escritura_poder_tab.fec_fecha, '' '') = coalesce(pendium_escritura_poder_tab1.fec_fecha, '' '') and coalesce(pendium_escritura_poder_tab.num_documentum_instr, '' '') = coalesce(pendium_escritura_poder_tab1.num_documentum_instr, '' '') and coalesce(pendium_escritura_poder_tab.fec_otorgamiento_instr, '' '') = coalesce(pendium_escritura_poder_tab1.fec_otorgamiento_instr, '' '') and pendium_escritura_poder_tab.num_licenciado = pendium_escritura_poder_tab1.num_licenciado and coalesce(pendium_escritura_poder_tab.num_insc_regpub, '' '') = coalesce(pendium_escritura_poder_tab1.num_insc_regpub, '' '') and coalesce(pendium_escritura_poder_tab.fec_registro, '' '') = coalesce(pendium_escritura_poder_tab1.fec_registro, '' '') and pendium_escritura_poder_tab1.ind_status = 1 and pendium_escritura_poder_tab.ind_status = 1 and pendium_escritura_poder_tab.ind_tipo_escritura = ''pe'' and pendium_escritura_poder_tab1.ind_tipo_escritura = ''pg'') and pendium_escritura_poder_tab.ind_status = 1 and pendium_apoderado_ep_tab.ind_tipoapoderado=1 and pendium_apoderado_ep_tab.ind_status <> 0'; /* dmap converted statement start *//* dmap converted statement */
if nullif(pstdes_escritura::text, '') is not null then
dinamicquery :=  concat(dinamicquery, ' AND ( PENDIUM_ESCRITURA_PODER_TAB.DES_ESCRITURA LIKE ', pstdes_escritura, ' )') ;/* dmap converted statement end */
end if;/* dmap converted statement start */
if nullif(pstdes_poder::text, '') is not null then
dinamicquery :=  concat(dinamicquery, ' AND (PENDIUM_OTORGAPODER_EP_TAB.NUM_PODERTIPO       IN (', pstdes_poder, '))') ;/* dmap converted statement end */
end if;/* dmap converted statement start */
if nullif(pstdes_tipopoder::text, '') is not null then
dinamicquery :=  concat(dinamicquery, ' AND ( PENDIUM_ESCRITURA_PODER_TAB.IND_TIPO_ESCRITURA IN (', pstdes_tipopoder, '))') ;/* dmap converted statement end */
end if;/* dmap converted statement start */
if nullif(pstdes_empresas::text, '') is not null then
dinamicquery :=  concat(dinamicquery, ' AND ( DERCORP_EMPRESA_TAB.ID_EMPRESA IN (', pstdes_empresas, '))') ;/* dmap converted statement end */
end if;/* dmap converted statement start */
if nullif(pstdes_apoderados::text, '') is not null then
dinamicquery :=  concat(dinamicquery, ' AND ( PENDIUM_APODERADO_EP_TAB.ID_EMPL_FK IN (', pstdes_apoderados, '))') ;/* dmap converted statement end */
end if;/* dmap converted statement start */
dinamicquery :=  concat(dinamicquery, '  order by  pendium_apoderado_ep_tab.desc_nom_empl,nom_empresa,pendium_escritura_poder_tab.ind_tipo_escritura desc,to_date(fec_otorgamiento_instr,''dd/mm/yyyy'') desc,pendium_otorgapoder_ep_tab.id_opoder_ep_pk, pendium_otorgapoder_ep_tab.num_order asc') ;/* dmap converted statement end */
open porcrsresultado for execute dinamicquery;end;
$body$
language plpgsql
